import{i as e}from"./index-xqFC_Jp1.js";var t=e({food:()=>n}),n={adelaide:{eateries:[{id:`lucias-pizza-spaghetti-bar`,name:`Lucia's Pizza & Spaghetti Bar`,area:`Central Market`,lat:-34.9296,lng:138.5961,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[9,22],order:[{name:`Spaghetti with house sugo`,price:17,note:`Pasta in the family's slow-cooked tomato and meat sauce`,wiki:`Bolognese sauce`},{name:`Pizza slice`,price:7,note:`Thick Italian-style slice from the counter`,wiki:`Pizza`},{name:`Espresso`,price:4,note:`Short, strong Italian coffee`,wiki:`Espresso`}],why:`A family-run Italian counter in the Central Market since 1957, serving simple pasta, pizza and coffee to generations of shoppers.`,tip:`Follows market hours, so closed Sundays and Mondays; grab a stool at the counter or a table in the market laneway.`,praise:[`Homely, honest Italian cooking`,`Good value for the city centre`,`Old-school family atmosphere`],watchOut:`Small and busy at Saturday lunch; expect to wait for a seat.`,reservation:`walk-in`,reservationNote:`No bookings; order at the counter and take any free seat`},{id:`bakery-on-oconnell`,name:`Bakery on O'Connell`,area:`North Adelaide`,lat:-34.9074,lng:138.596,kind:`bakery`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[6,16],order:[{name:`Pie floater`,price:12,note:`Meat pie upside down in pea soup with tomato sauce`,wiki:`Pie floater`},{name:`Kitchener bun`,price:5,note:`Sugared doughnut filled with jam and cream`,wiki:`Kitchener bun`},{name:`Pasty`,price:7,note:`Short-crust pastry stuffed with meat and vegetables`,wiki:`Pasty`}],why:`A round-the-clock North Adelaide bakery that keeps the pie floater tradition alive, feeding early risers and late-night crowds alike.`,tip:`Open 24 hours; it is the classic stop after a night out or a match at Adelaide Oval.`,praise:[`Proper pie floater any hour`,`Huge range of pies and cakes`,`Cheap and filling`],reservation:`walk-in`,reservationNote:`Counter service; a few tables inside and on the footpath`},{id:`pauls-seafood-on-gouger`,name:`Paul's Seafood on Gouger`,area:`Central Market`,lat:-34.9299,lng:138.5972,kind:`casual`,meals:[`lunch`,`dinner`],spend:[25,45],order:[{name:`King George whiting and chips`,price:34,note:`South Australia's prized whiting, battered or grilled, with chips`,wiki:`King George whiting`},{name:`Fish and chips`,price:22,note:`Local fish of the day with hot chips`,wiki:`Fish and chips`},{name:`Salt and pepper squid`,note:`Crisp-fried squid with lemon`,wiki:`Calamari`}],why:`A long-running, no-frills Gouger Street seafood house known for frying King George whiting just right at fair prices.`,tip:`Ask for the whiting grilled if you want to taste the fish itself; takeaway is cheaper.`,praise:[`Fresh, well-cooked local whiting`,`Generous portions`,`Fair prices for seafood`],watchOut:`Plain, canteen-style room; it is about the fish, not the decor.`,reservation:`recommended`,reservationNote:`Book for Friday and Saturday dinner; walk-ins usually fine at lunch`},{id:`gauchos-adelaide`,name:`Gaucho's`,area:`Central Market`,lat:-34.9299,lng:138.5976,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,110],order:[{name:`Grain- or grass-fed steak from the grill`,price:55,note:`Big cuts cooked over the Argentine-style parrilla`,wiki:`Asado`},{name:`Empanadas`,price:8,note:`Baked pastries filled with spiced beef`,wiki:`Empanada`},{name:`Chimichurri`,note:`Garlic, parsley and vinegar sauce for the steak`,wiki:`Chimichurri`}],why:`An Argentine steakhouse on Gouger Street since the 1990s, a city favourite for big, perfectly cooked steaks.`,tip:`Steaks are sized by weight; share a large cut and a couple of sides between two.`,praise:[`Excellent steaks cooked to order`,`Warm, lively atmosphere`,`Strong red wine list`],watchOut:`Prices climb quickly once you add sides and wine.`,reservation:`recommended`,reservationNote:`Book for weekend dinners; weekday walk-ins are often possible`},{id:`peel-st-restaurant`,name:`Peel St`,area:`West End`,lat:-34.9233,lng:138.5966,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,100],order:[{name:`Daily share plates`,note:`A changing menu mixing Middle Eastern and Southeast Asian flavours`},{name:`Whole fish of the day`,note:`Local fish cooked whole for the table`}],why:`The restaurant that helped turn Peel Street into a dining lane, cooking bold, produce-driven share plates in a busy, stylish room.`,tip:`Sit at the bar for a walk-in seat and a view of the kitchen.`,praise:[`Bold, punchy flavours`,`Great local wine list`,`Buzzing atmosphere`],watchOut:`Loud when full, and the changing menu means favourites come and go.`,reservation:`recommended`,reservationNote:`Book online for dinner, especially Thursday to Saturday`},{id:`rigonis-bistro`,name:`Rigoni's Bistro`,area:`West End`,lat:-34.9233,lng:138.5985,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[45,85],order:[{name:`Handmade pasta`,note:`Pasta made in-house with classic Italian sauces`},{name:`Gnocchi`,note:`Soft potato dumplings in a rich sauce`,wiki:`Gnocchi`},{name:`Veal saltimbocca`,note:`Veal with prosciutto and sage`,wiki:`Saltimbocca`}],why:`A Leigh Street institution for decades, serving traditional Italian food in a long, convivial room popular with the city's business crowd.`,tip:`Weekday lunches are busiest; it is usually closed on Sundays.`,praise:[`Classic, comforting Italian dishes`,`Friendly, professional service`,`Timeless bistro atmosphere`],reservation:`recommended`,reservationNote:`Book for weekday lunch and Friday dinner`},{id:`africola`,name:`Africola`,area:`East End`,lat:-34.9225,lng:138.6104,kind:`restaurant`,meals:[`dinner`],spend:[70,120],order:[{name:`Peri-peri chicken`,note:`Chargrilled chicken with a fiery African chilli sauce`,wiki:`Piri piri`},{name:`"Feed me" menu`,note:`Chef-chosen share menu of vegetables, breads and grilled meats`}],why:`A colourful East Terrace restaurant cooking loud, spice-driven African-inspired food over fire, one of Adelaide's most celebrated dining rooms.`,tip:`Go for the share menu with a group; the vegetable dishes are as good as the chicken.`,praise:[`Vibrant, fiery flavours`,`Fun, colourful setting`,`Excellent vegetable dishes`],watchOut:`Noisy and pricey; heat levels can be high.`,reservation:`recommended`,reservationNote:`Book online, especially for weekends; bar seats sometimes held for walk-ins`},{id:`hahndorf-inn`,name:`Hahndorf Inn`,area:`Hahndorf`,lat:-35.0286,lng:138.8098,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,65],order:[{name:`German platter`,note:`Bratwurst, mettwurst, smoked meats, sauerkraut and potato salad`,wiki:`Mettwurst`},{name:`Pork knuckle`,price:40,note:`Roasted pork hock with crackling and sauerkraut`,wiki:`Schweinshaxe`},{name:`Bratwurst`,note:`Grilled pork sausage with mustard`,wiki:`Bratwurst`}],why:`A Hahndorf pub dating from the 1860s, dishing up hearty German classics and steins of beer on the village main street.`,tip:`Ideal for lunch on an Adelaide Hills day trip; the outdoor tables fill quickly on sunny weekends.`,praise:[`Hearty German portions`,`Traditional pub atmosphere`,`Good German beer range`],watchOut:`Touristy and crowded on weekends and holidays.`,reservation:`recommended`,reservationNote:`Book for weekend lunches and groups; walk-ins fine midweek`}],dishes:{"Pie Floater":{price:[9,14],wiki:`Pie floater`},Yiros:{price:[13,20],wiki:`Gyros`},"King George Whiting":{price:[28,48],wiki:`King George whiting`},"Kitchener Bun":{price:[4,7],wiki:`Kitchener bun`},"Barossa Mettwurst":{price:[8,18],wiki:`Mettwurst`},FruChocs:{price:[6,12],wiki:`FruChocs`}}}},r=e({food:()=>i}),i={brisbane:{eateries:[{id:`jocelyns-provisions`,name:`Jocelyn's Provisions`,area:`Fortitude Valley (James Street)`,lat:-27.45634,lng:153.04015,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[8,20],order:[{name:`Sausage roll`,price:8,note:`Seasoned sausage meat baked in flaky pastry`,wiki:`Sausage roll`},{name:`Lemon meringue tart`,note:`Pastry case of tangy lemon curd topped with toasted meringue`},{name:`Flat white`,price:5,note:`Espresso with steamed milk and a thin layer of microfoam`,wiki:`Flat white`}],why:`A James Street bakery since 1996, known across Brisbane for its tarts, cakes, sausage rolls and fresh bread.`,tip:`The flagship is in Ada Lane opposite The Calile hotel; popular cakes sell out by early afternoon.`,praise:[`Beautiful tarts and cakes`,`Excellent sausage rolls`,`Charming neighbourhood bakery feel`],reservation:`walk-in`,reservationNote:`Order at the counter; mostly takeaway, so no booking needed`},{id:`morning-after`,name:`Morning After`,area:`West End`,lat:-27.48078,lng:153.00988,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[20,35],order:[{name:`Ricotta hotcakes`,price:24,note:`Fluffy ricotta pancakes with fruit and cream`},{name:`Breakfast carbonara`,price:26,note:`Brunch twist on pasta carbonara with egg and bacon`},{name:`Flat white`,price:5,note:`Espresso with steamed milk and a thin layer of microfoam`,wiki:`Flat white`}],why:`A bright, plant-filled West End brunch café serving breakfast all day, a local favourite for relaxed weekend mornings.`,tip:`Weekend waits are common; book or come before 8am. Combine with the Saturday Davies Park market.`,praise:[`Creative brunch dishes`,`Friendly service`,`Light-filled, leafy room`],reservation:`recommended`,reservationNote:`Book online for weekend brunch; weekdays are usually fine to walk in`},{id:`sushi-kotobuki`,name:`Sushi Kotobuki`,area:`East Brisbane`,lat:-27.47965,lng:153.04423,kind:`casual`,meals:[`lunch`,`dinner`],spend:[15,30],order:[{name:`Seared salmon aburi nigiri`,note:`Rice topped with salmon lightly torched and sauced`},{name:`Katsudon`,price:16,note:`Rice bowl of fried pork cutlet simmered with egg and onion`,wiki:`Katsudon`},{name:`Kotobuki roll`,note:`The house special sushi roll`}],why:`A busy, no-frills Japanese diner running since 2008, popular for generous sushi and rice bowls at low prices.`,tip:`Order at the counter and help yourself to water; closed Sundays.`,praise:[`Generous sushi at low prices`,`Popular seared salmon nigiri`,`Quick, efficient service`],watchOut:`Simple setting, and waits at peak dinner times.`,reservation:`walk-in`,reservationNote:`No booking needed; order at the counter and take a seat`},{id:`eat-street-northshore`,name:`Eat Street Northshore`,area:`Hamilton`,lat:-27.44415,lng:153.08025,kind:`market`,meals:[`dinner`],spend:[15,35],order:[{name:`Street food from the container stalls`,price:15,note:`Dishes from dozens of cuisines cooked in container kitchens`},{name:`Dessert from the stalls`,price:10,note:`Sweet treats such as churros, waffles or ice cream`}],why:`A riverside night market of shipping-container kitchens and bars, with food from around the world and live music.`,tip:`Open Friday to Sunday from 4pm; small entry fee, kids under 13 free. Take the CityCat to Northshore Hamilton.`,praise:[`Huge range of cuisines in one place`,`Fun night atmosphere with live music`,`Riverside setting`],watchOut:`Crowded on Saturday nights, and food costs add up on top of the entry fee.`,reservation:`walk-in`,reservationNote:`Pay entry at the gate and order at the stalls; no table bookings`},{id:`happy-boy`,name:`Happy Boy`,area:`Fortitude Valley (East Street)`,lat:-27.45745,lng:153.03465,kind:`casual`,meals:[`lunch`,`dinner`],spend:[30,55],order:[{name:`Pork and prawn wontons in chilli broth`,note:`Pork and prawn dumplings in a spicy chilli oil broth`},{name:`Mapo tofu`,note:`Silky tofu in a spicy, numbing Sichuan sauce with minced meat`,wiki:`Mapo tofu`},{name:`Chef's banquet (tables of four or more)`,price:45,note:`Chef's selection of dishes for the table`}],why:`A lively, industrial-styled Chinese eatery, in the Valley since 2017 and loved for punchy Sichuan-leaning dishes and Chinese barbecue.`,tip:`Popular for dinner; book ahead or expect to wait. Lunch has a shorter, cheaper menu.`,praise:[`Bold, spicy flavours`,`Lively, buzzy atmosphere`,`Great for sharing lots of dishes as a group`],reservation:`recommended`,reservationNote:`Book for dinner, especially on weekends; lunch is easier to walk into`},{id:`brisbane-german-club`,name:`Brisbane German Club`,area:`East Brisbane (Vulture Street)`,lat:-27.48439,lng:153.03682,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[28,50],order:[{name:`Pork schnitzel with chips and salad`,price:28,note:`Crumbed, fried pork cutlet with chips and salad`,wiki:`Schnitzel`},{name:`Crispy pork knuckle`,note:`Roasted pork hock with crackling skin`,wiki:`Schweinshaxe`},{name:`German beer on tap`,price:12,note:`Imported German lagers and wheat beers`}],why:`A long-running German club with a beer hall atmosphere, hearty schnitzels and imported beers on tap.`,tip:`Dress rules apply on Friday and Saturday nights from 6pm: no thongs or singlets.`,praise:[`Big, crisp schnitzels`,`Good German beers on tap`,`Fun beer hall atmosphere`],reservation:`recommended`,reservationNote:`Book for Friday and Saturday dinners; weekday walk-ins are usually fine`},{id:`breakfast-creek-hotel`,name:`Breakfast Creek Hotel`,area:`Albion (Breakfast Creek)`,lat:-27.44076,lng:153.04565,kind:`restaurant`,meals:[`lunch`,`dinner`,`late`],spend:[36,80],order:[{name:`Rump steak with bacon sauce`,price:36,note:`Chargrilled rump steak with creamy bacon sauce`},{name:`Beer from the wooden keg`,price:10,note:`Draught beer poured from a wooden keg`}],why:`A grand 1889 pub famous for picking your own steak from the cabinet to be chargrilled, served with its trademark bacon sauce.`,tip:`The Spanish Garden Steakhouse gets busy on weekends; the beer garden serves the same steaks.`,praise:[`Huge chargrilled steaks`,`Grand historic pub building`,`Beer poured straight from the wood`],watchOut:`Busy and noisy on weekends, and steaks are not cheap.`,reservation:`recommended`,reservationNote:`Book the steakhouse for weekend dinners; the beer garden is walk-in`},{id:`agnes`,name:`Agnes`,area:`Fortitude Valley`,lat:-27.45803,lng:153.03083,kind:`fine`,meals:[`dinner`],spend:[120,200],order:[{name:`Wood-fired bread and snacks`,note:`Bread and small bites cooked over the fire`},{name:`Hearth-cooked seafood and meats to share`,note:`Seafood and meats roasted over the wood fire, for sharing`}],why:`A moody, special-occasion restaurant where almost everything is cooked over wood fire, from bread to dessert.`,tip:`Book well ahead for dinner; the upstairs bar is easier to walk into.`,praise:[`Smoky, wood-fired flavours throughout`,`Moody, beautiful dining room`,`Excellent house bread`],watchOut:`Expensive; best kept for a special occasion.`,reservation:`recommended`,reservationNote:`Book weeks ahead for the dining room; walk in to the upstairs bar if it is full`}],dishes:{"Moreton Bay bugs":{price:[40,70],wiki:`Thenus`},Barramundi:{price:[32,45],wiki:`Barramundi`},"Queensland steak":{price:[32,70],wiki:`Steak`},"Fish and chips":{price:[14,25],wiki:`Fish and chips`},Lamington:{price:[5,9],wiki:`Lamington`},Mango:{price:[2,6],wiki:`Mango`}}}},a=e({food:()=>o}),o={cairns:{eateries:[{id:`rustys-markets`,name:`Rusty's Markets`,area:`City Centre (Grafton Street)`,lat:-16.9227,lng:145.7729,kind:`market`,meals:[`breakfast`,`lunch`],spend:[8,20],order:[{name:`Tropical fruit smoothie`,price:9,note:`Blended fresh mango, papaya, passionfruit or dragon fruit`},{name:`Rambutans and mangosteens`,price:6,note:`Sweet, juicy tropical fruit sold by the bag in season`,wiki:`Rambutan`},{name:`Breakfast from the food stalls`,price:14,note:`Coffee, crêpes, dumplings and hot breakfasts from market stalls`}],why:`The city's much-loved weekend market, piled with tropical fruit and local produce, with food stalls for a cheap breakfast.`,tip:`Open Friday to Sunday from early morning; come before 10am for the best fruit and fewer crowds.`,praise:[`Exotic fruit you rarely see elsewhere`,`Cheap, tasty breakfast stalls`,`Lively, local atmosphere`],watchOut:`Only open Friday to Sunday, and it gets hot and crowded by late morning.`,reservation:`walk-in`,reservationNote:`Market stalls; just turn up and buy`},{id:`meldrums-bakery`,name:`Meldrum's Bakery Café`,area:`City Centre (Grafton Street)`,lat:-16.9205,lng:145.7732,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[6,14],order:[{name:`Chunky steak pie`,price:7,note:`Hand-held pie of slow-cooked beef chunks in gravy`,wiki:`Meat pie`},{name:`Curry beef pie`,price:7,note:`Beef pie with a mild curry gravy`},{name:`Sausage roll`,price:5,note:`Seasoned sausage meat baked in flaky pastry`,wiki:`Sausage roll`}],why:`A long-running city bakery known for dozens of pie varieties, a cheap and filling Aussie lunch.`,tip:`Grab a pie to go and eat it on the Esplanade lawns, a few minutes' walk away.`,praise:[`Huge choice of pie fillings`,`Generous chunky steak pies`,`Cheap and quick`],watchOut:`Simple shop with limited seating; some fillings can be salty.`,reservation:`walk-in`,reservationNote:`Order at the counter; mostly takeaway`},{id:`cairns-night-markets-food-court`,name:`Cairns Night Markets Food Court`,area:`City Centre (Esplanade)`,lat:-16.9215,lng:145.779,kind:`market`,meals:[`dinner`,`late`],spend:[12,22],order:[{name:`Asian noodle and rice dishes`,price:14,note:`Thai, Chinese, Japanese and Indian plates from food-court stalls`},{name:`Fresh fruit juice`,price:7,note:`Tropical juices pressed at the stalls`}],why:`A cheap, cheerful food court inside the Esplanade night markets, handy for a quick dinner after a swim or reef day.`,tip:`Open every evening; eat early and then browse the stalls or stroll the Esplanade.`,praise:[`Wide choice of cuisines in one place`,`Low prices near the waterfront`,`Easy, casual evening meal`],watchOut:`Food-court quality varies from stall to stall.`,reservation:`walk-in`,reservationNote:`Order at the stalls and find a table; no bookings`},{id:`perrottas-at-the-gallery`,name:`Perrotta's at the Gallery`,area:`City Centre`,lat:-16.9233,lng:145.778,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[22,40],order:[{name:`Eggs Benedict`,price:24,note:`Poached eggs and hollandaise on toasted muffin`,wiki:`Eggs Benedict`},{name:`Local barramundi`,note:`Pan-fried barramundi from the lunch menu`,wiki:`Barramundi`},{name:`Flat white`,price:5,note:`Espresso with steamed milk and a thin layer of microfoam`,wiki:`Flat white`}],why:`A stylish street-front café at the Cairns Art Gallery, a long-time local favourite for breakfast and lunch on a shady terrace.`,tip:`Pair it with a free look around the gallery; fresh juices are a good cool-down on hot days.`,praise:[`Excellent breakfasts and coffee`,`Pleasant shaded terrace`,`Handy central location`],reservation:`recommended`,reservationNote:`Walk-ins usually fine; book for weekend brunch or groups`},{id:`prawn-star`,name:`Prawn Star`,area:`Marlin Marina`,lat:-16.9221,lng:145.7834,kind:`casual`,meals:[`lunch`,`dinner`],spend:[35,80],order:[{name:`Fresh tiger prawns`,price:35,note:`Chilled local prawns, peeled at the table`,wiki:`Prawn`},{name:`Seafood platter`,price:80,note:`Prawns, bugs, oysters and crab piled on ice`},{name:`Oysters`,note:`Freshly shucked oysters with lemon`,wiki:`Oyster`}],why:`A floating seafood shack on a moored trawler in the marina, serving cold prawns and platters straight off the boats.`,tip:`Seating on deck is limited and it is busiest at sunset; come mid-afternoon for an easy table.`,praise:[`Very fresh, sweet prawns`,`Fun, casual setting on a boat`,`Great marina views`],watchOut:`Cold seafood only and simple service; not cheap for what is basically a picnic on deck.`,reservation:`walk-in`,reservationNote:`No bookings; tables on deck go first come, first served`},{id:`salt-house`,name:`Salt House`,area:`Marlin Marina`,lat:-16.9201,lng:145.7825,kind:`restaurant`,meals:[`lunch`,`dinner`,`late`],spend:[40,85],order:[{name:`Meats from the Argentinian grill`,price:45,note:`Steaks and meats cooked over a wood-fired parrilla`,wiki:`Asado`},{name:`Local seafood dishes`,note:`Reef fish, prawns and other local catch`},{name:`Sunset cocktail`,price:22,note:`Tropical cocktails at the outdoor bar`}],why:`A big, breezy waterfront restaurant and bar on the marina point, loved for sunset drinks and grilled meats and seafood.`,tip:`The restaurant and bar menus differ; day beds on the lawn go fast at sunset.`,praise:[`Spectacular inlet and mountain views`,`Buzzy sunset atmosphere`,`Good grilled meats and seafood`],watchOut:`Can be loud and busy on weekends, and prices reflect the location.`,reservation:`recommended`,reservationNote:`Book the restaurant for dinner; the bar is walk-in`},{id:`dundees-waterfront`,name:`Dundee's on the Waterfront`,area:`Marlin Marina`,lat:-16.9241,lng:145.781,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,95],order:[{name:`Seafood platter`,price:90,note:`Prawns, bugs, oysters, fish and crab to share`},{name:`Lime and chilli tiger prawns`,note:`Local prawns tossed with lime and chilli`,wiki:`Prawn`},{name:`Grilled barramundi`,note:`Local barramundi with seasonal sides`,wiki:`Barramundi`}],why:`A long-established seafood restaurant on the Harbour Lights boardwalk, watching the reef boats come and go.`,tip:`Ask for an outdoor table on the boardwalk; lunch is quieter and better value.`,praise:[`Fresh local seafood`,`Lovely marina-side setting`,`Friendly, polished service`],reservation:`recommended`,reservationNote:`Book for dinner, especially for an outdoor table`},{id:`ochre-restaurant`,name:`Ochre Restaurant`,area:`Marlin Marina`,lat:-16.9239,lng:145.7811,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[70,140],order:[{name:`Chargrilled kangaroo sirloin`,note:`Lean kangaroo cooked rare with native accompaniments`,wiki:`Kangaroo meat`},{name:`Australian antipasto platter`,note:`Tasting plate of bush-food-inspired bites`},{name:`Native tasting menu`,note:`Several courses built around Australian native ingredients`}],why:`A pioneer of Australian native ingredients since the 1990s, now on the marina boardwalk with views to the ranges.`,tip:`Try the tasting plate if new to bush foods; closed Sundays.`,praise:[`Unique native Australian flavours`,`Beautiful waterfront position`,`Knowledgeable, welcoming staff`],watchOut:`Expensive, and the native flavours are not to everyone's taste.`,reservation:`recommended`,reservationNote:`Book for dinner, especially in the dry season (May to October)`}],dishes:{Barramundi:{price:[30,48],wiki:`Barramundi`},"Mud crab":{price:[70,140],wiki:`Scylla serrata`},"Fresh prawns":{price:[20,40],wiki:`Prawn`},"Coral trout":{price:[40,60],wiki:`Leopard coral grouper`},"Tropical fruit":{price:[3,10]},"Kangaroo and native bush foods":{price:[35,50],wiki:`Kangaroo meat`}}}},s=e({food:()=>c}),c={hobart:{eateries:[{id:`flippers-fish-punt`,name:`Flippers Fish Punt`,area:`Constitution Dock`,lat:-42.8832,lng:147.332,kind:`street`,meals:[`lunch`,`dinner`],spend:[14,28],order:[{name:`Flathead and chips`,price:18,note:`Battered local flathead fillets with hot chips`,wiki:`Fish and chips`},{name:`Scallops and chips`,note:`Crumbed Tasmanian scallops with chips`,wiki:`Scallop`},{name:`Seafood basket`,note:`Fish, scallops, squid and prawns fried together`}],why:`A bright floating fish-and-chip punt in Constitution Dock, frying local seafood to order for decades.`,tip:`Order at the hatch and eat on the dockside benches; it closes early in the evening in winter.`,praise:[`Fresh fish, fried to order`,`Unbeatable dockside setting`,`Quick and good value`],watchOut:`Queues build on sunny weekends, and the seagulls are bold.`,reservation:`walk-in`,reservationNote:`No bookings; queue at the window and eat on the dock`},{id:`mures-hobart`,name:`Mures`,area:`Victoria Dock`,lat:-42.882,lng:147.3327,kind:`casual`,meals:[`lunch`,`dinner`],spend:[20,75],order:[{name:`Fish and chips`,price:22,note:`Blue-eye or flathead in batter with chips`,wiki:`Fish and chips`},{name:`Tasmanian oysters`,note:`Freshly shucked local Pacific oysters`,wiki:`Pacific oyster`},{name:`Seafood chowder`,note:`Creamy soup thick with local fish and shellfish`,wiki:`Chowder`}],why:`A family seafood business since 1973 with its own fishing boat: a casual counter downstairs and a harbour-view dining room upstairs.`,tip:`The Lower Deck is order-at-the-counter and cheaper; book the Upper Deck for a sit-down dinner overlooking the docks.`,praise:[`Very fresh local seafood`,`Options for every budget`,`Views over the fishing fleet`],watchOut:`The Lower Deck is busy and canteen-like at peak times.`,reservation:`recommended`,reservationNote:`Book the Upper Deck for dinner; the Lower Deck is walk-in`},{id:`jackman-and-mcross`,name:`Jackman & McRoss`,area:`Battery Point`,lat:-42.89,lng:147.331,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[8,20],order:[{name:`Scallop pie`,price:12,note:`Tasmanian scallops in a light curry sauce in pastry`},{name:`Croissant`,price:5,note:`Buttery French pastry`,wiki:`Croissant`},{name:`Flat white`,price:5,note:`Espresso with velvety steamed milk`,wiki:`Flat white`}],why:`A beloved Battery Point bakery-café with a cabinet full of pies, tarts and pastries and a cosy heritage shopfront.`,tip:`Order at the counter and grab a window table; perfect fuel before walking Battery Point.`,praise:[`Excellent pies and pastries`,`Charming old-world setting`,`Reasonable prices`],watchOut:`Tight space and queues on weekend mornings.`,reservation:`walk-in`,reservationNote:`No bookings; order at the counter`},{id:`machine-laundry-cafe`,name:`Machine Laundry Café`,area:`Salamanca`,lat:-42.8869,lng:147.3296,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[15,30],order:[{name:`Big breakfast`,note:`Eggs, bacon, sausage and toast for a hearty start`,wiki:`Full breakfast`},{name:`Eggs Benedict`,price:24,note:`Poached eggs and hollandaise on toasted bread`,wiki:`Eggs Benedict`},{name:`Flat white`,price:5,note:`Espresso with velvety steamed milk`,wiki:`Flat white`}],why:`A quirky, colourful Salamanca Square café, a breakfast favourite for years, where you can literally do your washing while you eat.`,tip:`Grab an outdoor table in the square; it closes mid-afternoon.`,praise:[`Hearty, good-value breakfasts`,`Fun retro setting`,`Friendly service`],reservation:`walk-in`,reservationNote:`No bookings; expect a short wait for a table on market Saturdays`},{id:`drunken-admiral`,name:`The Drunken Admiral`,area:`Old Wharf`,lat:-42.8813,lng:147.3341,kind:`restaurant`,meals:[`dinner`],spend:[55,95],order:[{name:`Seafood chowder`,note:`Hearty creamy chowder loaded with fish and shellfish`,wiki:`Chowder`},{name:`Tasmanian oysters`,note:`Local Pacific oysters natural or dressed`,wiki:`Pacific oyster`},{name:`Seafood platter`,note:`A share platter of hot and cold local seafood`}],why:`A seafood restaurant in an old waterfront warehouse since the 1970s, crammed with nautical memorabilia and serving generous Tasmanian seafood.`,tip:`Dinner only; ask for a booth to soak up the shipwreck-museum decor.`,praise:[`Generous seafood servings`,`Characterful nautical setting`,`Good local wines`],watchOut:`The theme-pub decor is not for everyone, and it is pricey.`,reservation:`recommended`,reservationNote:`Book for dinner, especially in summer and on weekends`},{id:`ball-and-chain-grill`,name:`Ball & Chain Grill`,area:`Salamanca`,lat:-42.8873,lng:147.3307,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,100],order:[{name:`Chargrilled Tasmanian steak`,price:50,note:`Local grass-fed beef cooked over a charcoal grill`,wiki:`Steak`},{name:`Tasmanian salmon`,note:`Grilled local salmon fillet`,wiki:`Salmon as food`}],why:`A Salamanca Place grill house in a convict-built sandstone warehouse, cooking Tasmanian beef over charcoal since the 1980s.`,tip:`Ask for your steak just as you like it; the salad bar suits lighter appetites.`,praise:[`Well-cooked local steaks`,`Atmospheric sandstone interior`,`Solid Tasmanian wine list`],watchOut:`Old-fashioned style and not cheap.`,reservation:`recommended`,reservationNote:`Book for dinner on weekends and in summer`},{id:`smolt-hobart`,name:`Smolt`,area:`Salamanca`,lat:-42.8868,lng:147.3301,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[40,80],order:[{name:`Tasmanian salmon`,note:`Local salmon prepared in a Mediterranean style`,wiki:`Salmon as food`},{name:`Share plates`,note:`Spanish- and Italian-leaning small plates built on local produce`}],why:`A relaxed Salamanca Square restaurant mixing Mediterranean cooking with Tasmanian produce, handy all day from breakfast to dinner.`,tip:`Sit on the square in fine weather; good for a light market-day lunch.`,praise:[`Fresh local produce`,`Pleasant square setting`,`Friendly service`],reservation:`recommended`,reservationNote:`Book for dinner; walk-ins usually fine at breakfast and lunch`},{id:`me-wah-hobart`,name:`Me Wah`,area:`Sandy Bay`,lat:-42.8996,lng:147.3263,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,110],order:[{name:`Peking duck`,note:`Crisp roast duck wrapped in pancakes with hoisin`,wiki:`Peking duck`},{name:`Xiao long bao`,note:`Soup-filled steamed pork dumplings`,wiki:`Xiaolongbao`},{name:`Tasmanian seafood stir-fry`,note:`Local seafood such as scallops or lobster cooked Cantonese style`}],why:`Hobart's grandest Chinese restaurant for decades, serving refined Cantonese and regional dishes with local seafood in an elegant dining room.`,tip:`Yum cha at weekend lunch is the most fun way to try it.`,praise:[`Polished, elegant Chinese cooking`,`Excellent Tasmanian seafood dishes`,`Attentive service`],watchOut:`Expensive by Hobart standards, and out of the city centre.`,reservation:`recommended`,reservationNote:`Book ahead for dinner and weekend yum cha`}],dishes:{"Scallop Pie":{price:[9,14]},"Tasmanian Oysters":{price:[20,40],wiki:`Pacific oyster`},"Flathead and Chips":{price:[17,30],wiki:`Fish and chips`},"Tasmanian Salmon":{price:[30,45],wiki:`Salmon as food`},"Leatherwood Honey":{price:[10,20]},"Tasmanian Whisky":{price:[14,30],wiki:`Australian whisky`}}}},l=e({food:()=>u}),u={perth:{eateries:[{id:`cicerellos-fremantle`,name:`Cicerello's`,area:`Fishing Boat Harbour, Fremantle`,lat:-32.05852,lng:115.74307,kind:`casual`,meals:[`lunch`,`dinner`],spend:[25,45],order:[{name:`Fish and chips`,price:26,note:`Battered fish fillets with a pile of hot chips`,wiki:`Fish and chips`},{name:`Seafood basket`,price:35,note:`Fried fish, prawns, squid and scallops with chips`,wiki:`Seafood basket`},{name:`Grilled snapper`,note:`Local fish grilled instead of battered, with salad and chips`}],why:`A family-run fish-and-chip institution on the Fremantle harbour boardwalk, frying local fish for generations of Perth families.`,tip:`Order at the counter, then eat on the boardwalk at sunset; guard your chips from the seagulls.`,praise:[`Classic harbourside fish and chips`,`Generous portions`,`Fun waterfront setting`],watchOut:`Touristy and busy on weekends; quality can feel mass-produced at peak times.`,reservation:`walk-in`,reservationNote:`No bookings; order at the counter and find a table inside or on the boardwalk`},{id:`little-creatures-fremantle`,name:`Little Creatures Brewery`,area:`Fishing Boat Harbour, Fremantle`,lat:-32.05944,lng:115.74466,kind:`bar`,meals:[`lunch`,`dinner`],spend:[35,70],order:[{name:`Little Creatures Pale Ale`,price:13,note:`The hoppy, citrusy pale ale brewed on site`,wiki:`Pale ale`},{name:`Wood-fired pizza`,price:28,note:`Thin, blistered pizza from the brewery oven`,wiki:`Pizza`},{name:`Chilli mussels`,note:`Local mussels in a spicy tomato sauce with bread, when on the menu`}],why:`The brewery that put Fremantle craft beer on the map, in a vast harbourside shed with the brewhouse on show and share plates to match.`,tip:`Grab a deck table overlooking the boats; brewery tours run on weekends and are worth booking.`,praise:[`Fresh beer straight from the brewhouse`,`Buzzing harbourside warehouse`,`Good pizzas for sharing`],watchOut:`Loud and packed on sunny weekends.`,reservation:`recommended`,reservationNote:`Book online for groups or weekend evenings; walk-ins fine at quieter times`},{id:`ginos-fremantle`,name:`Gino's`,area:`South Terrace, Fremantle`,lat:-32.0556,lng:115.74712,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[8,25],order:[{name:`Cappuccino`,price:5.5,note:`Italian-style espresso topped with frothed milk`,wiki:`Cappuccino`},{name:`Affogato`,price:8,note:`Vanilla gelato drowned in a shot of hot espresso`,wiki:`Affogato`},{name:`Toasted focaccia`,price:15,note:`Grilled Italian bread filled with ham, cheese and tomato`}],why:`The best-known espresso bar on Fremantle's Cappuccino Strip, serving Italian coffee to pavement tables since the 1980s.`,tip:`Order and pay at the counter, then nab a street-side seat for people-watching.`,praise:[`Strong, classic Italian coffee`,`Great spot for people-watching`,`Old-school Fremantle character`],reservation:`walk-in`,reservationNote:`No bookings; order at the counter and take any free table`},{id:`chu-bakery`,name:`Chu Bakery`,area:`William Street, Highgate`,lat:-31.93939,lng:115.86485,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[6,18],order:[{name:`Croissant`,price:6,note:`Flaky, buttery French pastry`,wiki:`Croissant`},{name:`Matcha choux puff`,price:6,note:`Crisp choux pastry filled with green tea cream`,wiki:`Choux pastry`},{name:`Filled baguette`,price:10,note:`Fresh baguette with chicken or tuna filling`}],why:`A small Japanese-style bakery opposite Hyde Park known for delicate pastries and cream puffs, a long-time favourite with locals.`,tip:`Come in the morning before the most popular pastries sell out; there is little seating, so plan a Hyde Park picnic.`,praise:[`Light, delicate pastries`,`Famous cream-filled choux`,`Reasonable prices`],watchOut:`Tiny shop with limited seating; popular items sell out early.`,reservation:`walk-in`,reservationNote:`No bookings; queue at the counter`},{id:`chicho-gelato`,name:`Chicho Gelato`,area:`William Street, Northbridge`,lat:-31.9496,lng:115.85917,kind:`dessert`,meals:[`dinner`,`late`],spend:[7,12],order:[{name:`Gelato, two flavours`,price:9,note:`Dense Italian-style ice cream in rotating creative flavours`,wiki:`Gelato`},{name:`Pistachio gelato`,price:8,note:`Nutty gelato made with real pistachios`,wiki:`Pistachio`}],why:`Northbridge's gelato hotspot, churning inventive flavours in small batches and drawing queues out the door late into the evening.`,tip:`Open afternoons until late; the line moves fast, and staff happily offer tastings.`,praise:[`Creative, changing flavours`,`Smooth, rich texture`,`Open late for dessert after dinner`],watchOut:`Long queues on warm evenings and weekends.`,reservation:`walk-in`,reservationNote:`No bookings; join the queue`},{id:`mary-street-bakery-highgate`,name:`Mary Street Bakery`,area:`Beaufort Street, Highgate`,lat:-31.93832,lng:115.86956,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[20,40],order:[{name:`Doughnut`,price:7,note:`Sugar-dusted doughnut with a seasonal filling`,wiki:`Doughnut`},{name:`Smashed avocado on toast`,price:22,note:`Avocado on sourdough with feta and herbs`,wiki:`Avocado toast`},{name:`Flat white`,price:5.5,note:`Espresso with silky steamed milk`,wiki:`Flat white`}],why:`The original Beaufort Street branch of a beloved Perth café, known for filled doughnuts, house-baked bread and hearty brunch plates.`,tip:`Weekend brunch gets busy by 9am; doughnuts are also sold to take away from the counter.`,praise:[`Excellent filled doughnuts`,`Generous brunch plates`,`Good coffee`],watchOut:`Weekend waits for a table.`,reservation:`walk-in`,reservationNote:`Mostly walk-in; put your name down at the door on busy weekend mornings`},{id:`long-chim-perth`,name:`Long Chim`,area:`State Buildings, CBD`,lat:-31.95561,lng:115.86019,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,100],order:[{name:`Green papaya salad`,price:22,note:`Pounded green papaya with chilli, lime, peanuts and dried shrimp`,wiki:`Green papaya salad`},{name:`Massaman curry`,price:38,note:`Rich, mild curry of slow-cooked meat with potatoes and peanuts`,wiki:`Massaman curry`},{name:`Pad see ew`,price:30,note:`Wide rice noodles wok-fried with soy, egg and Chinese broccoli`,wiki:`Pad see ew`}],why:`Fiery, punchy Thai street-food cooking from chef David Thompson in a buzzy basement of the heritage State Buildings.`,tip:`Dishes are made for sharing and some are very hot; ask staff to steer you if you prefer milder flavours.`,praise:[`Bold, authentic Thai flavours`,`Lively, stylish room`,`Good cocktails`],watchOut:`Loud room, and the spice level is genuinely high.`,reservation:`recommended`,reservationNote:`Book online for dinner, especially Thursday to Saturday; lunch walk-ins often fine`},{id:`frasers-kings-park`,name:`Fraser's`,area:`Kings Park`,lat:-31.95962,lng:115.84357,kind:`fine`,meals:[`lunch`,`dinner`],spend:[90,160],order:[{name:`Western rock lobster`,note:`WA rock lobster served seasonally, often grilled with butter`,wiki:`Panulirus cygnus`},{name:`Local fish of the day`,note:`Seasonal WA fish such as dhufish or snapper`},{name:`Pavlova`,note:`Meringue with cream and fresh fruit`,wiki:`Pavlova`}],why:`A Kings Park landmark since 1993, serving modern Australian dishes built on WA seafood with floor-to-ceiling views over the river and skyline.`,tip:`Book a window table at lunch for the clearest view, or at sunset as the city lights come on.`,praise:[`Spectacular river and city views`,`Strong WA seafood`,`Polished service`],watchOut:`Pricey; the view is part of what you pay for.`,reservation:`recommended`,reservationNote:`Book ahead for window tables and weekends; weekday lunches have more space`}],dishes:{"Western Rock Lobster":{price:[55,130],wiki:`Panulirus cygnus`},"Fish and Chips":{price:[18,32],wiki:`Fish and chips`},"Chilli Mussels":{price:[28,42]},"Meat Pie":{price:[6,11],wiki:`Meat pie (Australia and New Zealand)`},"Flat White":{price:[4.5,6],wiki:`Flat white`},Pavlova:{price:[12,20],wiki:`Pavlova`}}}},d=e({food:()=>f}),f={sydney:{eateries:[{id:`sydney-fish-market`,name:`Sydney Fish Market`,area:`Blackwattle Bay, Glebe`,lat:-33.8738,lng:151.1892,kind:`market`,meals:[`breakfast`,`lunch`],spend:[20,45],order:[{name:`Sydney rock oysters (half dozen)`,price:20,note:`Small, briny native oysters, usually eaten raw with lemon`,wiki:`Saccostrea glomerata`},{name:`Fish and chips`,price:18,note:`Battered or grilled fish with hot chips`,wiki:`Fish and chips`},{name:`Sashimi platter`,price:25,note:`Sliced raw fish such as salmon and tuna`,wiki:`Sashimi`}],why:`Australia's biggest seafood market, which moved into a striking new waterfront building on Blackwattle Bay in January 2026.`,tip:`Come before 11am for the freshest choice and fewer crowds; old maps may still point to the closed Pyrmont site.`,praise:[`Huge choice of very fresh seafood`,`Good-value oysters and sashimi`,`Lively, working market atmosphere`],watchOut:`Very busy on weekends and before Christmas; seating can be hard to find.`,reservation:`walk-in`,reservationNote:`No bookings; buy from the stalls and find a seat on the waterfront deck`},{id:`harrys-cafe-de-wheels`,name:`Harry's Café de Wheels`,area:`Woolloomooloo`,lat:-33.8694,lng:151.2205,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[8,15],order:[{name:`Tiger pie (meat pie with mash, peas and gravy)`,price:12,note:`Meat pie topped with mashed potato, mushy peas and gravy`,wiki:`Meat pie (Australia and New Zealand)`},{name:`Hot dog de Wheels`,price:10,note:`The cart's house hot dog with a pile of toppings`,wiki:`Hot dog`}],why:`A pie cart on the Woolloomooloo wharf since 1938, a late-night Sydney landmark for meat pies topped with mushy peas and gravy.`,tip:`Open late, especially on weekends; walk there from the Botanic Garden or Art Gallery.`,praise:[`Iconic late-night pie stop`,`Hearty, cheap comfort food`,`Wharf-side setting by the harbour`],watchOut:`Very few seats; most people eat standing or on the wharf.`,reservation:`walk-in`,reservationNote:`Pie cart: order at the window, no bookings`},{id:`bourke-street-bakery-surry-hills`,name:`Bourke Street Bakery`,area:`Surry Hills`,lat:-33.8905,lng:151.2142,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[8,18],order:[{name:`Pork and fennel sausage roll`,price:9,note:`Pork and fennel sausage meat wrapped in flaky puff pastry`,wiki:`Sausage roll`},{name:`Ginger brûlée tart`,price:8,note:`Custard tart with ginger and a caramelised sugar top`},{name:`Sourdough loaf`,price:10,note:`Crusty naturally leavened bread`,wiki:`Sourdough`}],why:`The original corner shop (2004) of a much-loved Sydney bakery, known for sausage rolls, tarts and sourdough.`,tip:`Tiny shop with a few pavement seats; it often sells out of favourites by early afternoon.`,praise:[`Flaky, well-seasoned sausage rolls`,`Excellent sourdough`,`Tarts with crisp, buttery pastry`],reservation:`walk-in`,reservationNote:`Order at the counter; takeaway is easiest as seats are few`},{id:`bills-surry-hills`,name:`bills`,area:`Surry Hills (Crown St)`,lat:-33.8859,lng:151.2131,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[25,45],order:[{name:`Ricotta hotcakes with banana and honeycomb butter`,price:27,note:`Light ricotta pancakes with banana and honeycomb butter`},{name:`Smashed avocado on toast`,price:22,note:`Crushed avocado on toasted sourdough`,wiki:`Avocado toast`},{name:`Flat white`,price:5,note:`Espresso with steamed milk and a thin layer of microfoam`,wiki:`Flat white`}],why:`Bill Granger's café group, founded in Sydney in 1993, helped make the Australian brunch famous with ricotta hotcakes and creamy scrambled eggs.`,tip:`Weekend brunch gets busy; arrive early or come for a weekday breakfast.`,praise:[`Fluffy ricotta hotcakes`,`Creamy scrambled eggs`,`Bright, relaxed café feel`],watchOut:`Brunch prices are high.`,reservation:`walk-in`,reservationNote:`Mostly walk-in; put your name down and expect a wait for weekend brunch`},{id:`mamak-haymarket`,name:`Mamak`,area:`Chinatown / Haymarket`,lat:-33.8785,lng:151.2047,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[15,30],order:[{name:`Roti canai with curry`,price:10,note:`Flaky griddled flatbread served with curry for dipping`,wiki:`Roti canai`},{name:`Nasi lemak`,price:20,note:`Coconut rice with sambal, peanuts, anchovies, egg and curry`,wiki:`Nasi lemak`},{name:`Roti tisu`,price:14,note:`Paper-thin, crisp cone of roti, often drizzled with condensed milk`}],why:`A busy Malaysian eatery in Chinatown where roti is stretched and flipped in the front window; a city favourite for cheap, late meals.`,tip:`No bookings; queues are longest on weekend evenings but move quickly.`,praise:[`Flaky roti made fresh in the window`,`Cheap, tasty Malaysian food`,`Fast service once seated`],reservation:`walk-in`,reservationNote:`Join the queue outside; tables turn over fast`},{id:`chat-thai-haymarket`,name:`Chat Thai`,area:`Thaitown, Haymarket`,lat:-33.8805,lng:151.2055,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[20,35],order:[{name:`Pad see ew`,price:20,note:`Wide rice noodles stir-fried with soy sauce, Chinese broccoli and egg`,wiki:`Pad see ew`},{name:`Boat noodles`,price:18,note:`Noodles in a rich, dark, spiced broth with beef or pork`,wiki:`Boat noodles`},{name:`Mango sticky rice`,price:12,note:`Sweet coconut sticky rice with ripe mango`,wiki:`Mango sticky rice`}],why:`The Campbell Street flagship of a long-running Sydney Thai group, popular for street-style noodles, curries and desserts.`,tip:`Put your name on the list at the door and stay close; numbers are called quickly.`,praise:[`Authentic Thai street-style flavours`,`Fast, efficient service`,`Open late`],watchOut:`Cramped and loud, with queues at peak times.`,reservation:`walk-in`,reservationNote:`No bookings for small groups; add your name to the list at the door`},{id:`doyles-on-the-beach`,name:`Doyles on the Beach`,area:`Watsons Bay`,lat:-33.8447,lng:151.2818,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[45,100],order:[{name:`Fish and chips`,price:38,note:`Battered or grilled fish with hot chips`,wiki:`Fish and chips`},{name:`Sydney rock oysters`,price:36,note:`Small, briny native oysters served raw`,wiki:`Saccostrea glomerata`}],why:`A family-run seafood restaurant on the sand at Watsons Bay, from a family serving seafood here since the late 1800s.`,tip:`Take the ferry from Circular Quay; book for a weekend lunch table near the sand.`,praise:[`Beachside views across the harbour to the city`,`Classic fish and chips by the water`,`A great day out with the ferry ride`],watchOut:`Pricey for fish and chips; you pay for the setting.`,reservation:`recommended`,reservationNote:`Book for weekend lunch or sunset dinner; weekday lunch is often walk-in`},{id:`quay`,name:`Quay`,area:`Circular Quay (Overseas Passenger Terminal)`,lat:-33.8582,lng:151.2097,kind:`fine`,meals:[`lunch`,`dinner`],spend:[300,450],order:[{name:`Tasting menu`,price:330,note:`Multi-course menu of seasonal, produce-led dishes`},{name:`Snow egg dessert (when on the menu)`,note:`Signature layered dessert of poached meringue, granita and fruit`}],why:`Chef Peter Gilmore's harbourside restaurant facing the Opera House, a leader of modern Australian fine dining since 2001.`,tip:`Book well ahead and ask for a window table; lunch sittings are popular for the harbour views.`,praise:[`Breathtaking Opera House and harbour views`,`Refined, beautiful dishes built on Australian produce`,`Polished, attentive service`],watchOut:`Very expensive, and dinner books out weeks ahead.`,reservation:`essential`,reservationNote:`Book online well ahead, often a month or more for dinner; walk-ins are rare`}],dishes:{"Sydney rock oysters":{price:[24,45],wiki:`Saccostrea glomerata`},"Fish and chips by the beach":{price:[15,25],wiki:`Fish and chips`},"Smashed avo and a flat white":{price:[20,30],wiki:`Avocado toast`},"Meat pie":{price:[6,12],wiki:`Meat pie`},Pavlova:{price:[10,18],wiki:`Pavlova`},Lamington:{price:[4,8],wiki:`Lamington`}}},melbourne:{eateries:[{id:`queen-victoria-market`,name:`Queen Victoria Market`,area:`CBD north`,lat:-37.8076,lng:144.9568,kind:`market`,meals:[`breakfast`,`lunch`],spend:[8,25],order:[{name:`Hot jam doughnuts from the American Doughnut Kitchen van`,price:2,note:`Fried yeast doughnuts filled with hot jam and rolled in sugar`,wiki:`Jelly doughnut`},{name:`Bratwurst roll from the deli hall`,price:11,note:`Grilled bratwurst in a bread roll with mustard and sauerkraut`}],why:`A huge open-air market trading since 1878, with a deli hall and a doughnut van that has been frying hot jam doughnuts since the 1950s.`,tip:`Closed Mondays and Wednesdays; mornings are best for the doughnut van and deli hall.`,praise:[`Hot jam doughnuts are a must`,`Huge range of fresh produce and deli goods`,`Lively, historic market`],watchOut:`Weekends are crowded and many stalls pack up by early afternoon.`,reservation:`walk-in`,reservationNote:`Market: wander the stalls, no bookings`},{id:`pellegrinis-espresso-bar`,name:`Pellegrini's Espresso Bar`,area:`Bourke Street (Paris End)`,lat:-37.8116,lng:144.9711,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[12,25],order:[{name:`Spaghetti bolognese`,price:18,note:`Spaghetti in a slow-cooked meat sauce`,wiki:`Spaghetti bolognese`},{name:`Espresso`,price:4,note:`Short, strong shot of coffee`,wiki:`Espresso`},{name:`Watermelon granita`,price:6,note:`Shaved iced watermelon dessert`,wiki:`Granita`}],why:`An Italian espresso bar open since 1954, credited as one of Melbourne's first, little changed with its long counter and simple pasta.`,tip:`Sit at the bar; there is no menu, just ask what is on today.`,praise:[`Retro 1950s atmosphere`,`Simple, cheap homestyle pasta`,`Friendly, old-school staff`],watchOut:`Food is simple rather than refined, and seating is tight.`,reservation:`walk-in`,reservationNote:`Walk in and grab a stool at the bar; no bookings`},{id:`higher-ground`,name:`Higher Ground`,area:`CBD west (Little Bourke St)`,lat:-37.8164,lng:144.9539,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[25,40],order:[{name:`Ricotta hotcake`,price:26,note:`Single thick ricotta pancake with seasonal toppings`},{name:`Flat white`,price:5,note:`Espresso with steamed milk and a thin layer of microfoam`,wiki:`Flat white`}],why:`A soaring all-day café in a heritage-listed 1890s power station near Southern Cross Station, a go-to for Melbourne-style brunch since 2015.`,tip:`Weekend brunch waits can be long; weekdays are easier.`,praise:[`Stunning lofty heritage interior`,`Thick, fluffy ricotta hotcake`,`Good coffee`],watchOut:`Pricey, and it gets noisy when full.`,reservation:`walk-in`,reservationNote:`Walk in and put your name down; weekday mornings have the shortest waits`},{id:`lune-croissanterie-fitzroy`,name:`Lune Croissanterie`,area:`Fitzroy`,lat:-37.7987,lng:144.9801,kind:`bakery`,meals:[`breakfast`],spend:[8,20],order:[{name:`Plain croissant`,price:8,note:`Classic all-butter croissant`,wiki:`Croissant`},{name:`Cruffin of the day`,price:10,note:`Croissant-muffin hybrid with a changing filling`}],why:`A converted Fitzroy warehouse where pastry is laminated inside a glass cube; the croissants gained a cult following.`,tip:`Pre-order online or arrive early; lines often stretch up the street and favourites sell out.`,praise:[`Very flaky, buttery croissants`,`Pastry-making on show in the glass-walled lab`,`Creative cruffins and specials`],reservation:`walk-in`,reservationNote:`Queue at the counter, or pre-order online to collect and skip the line`},{id:`stalactites`,name:`Stalactites`,area:`Greek Precinct (Lonsdale St)`,lat:-37.8114,lng:144.9665,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[20,40],order:[{name:`Lamb souvlaki`,price:18,note:`Grilled lamb with tomato, onion and tzatziki wrapped in pita`,wiki:`Souvlaki`},{name:`Dip platter with pita`,price:18,note:`Greek dips such as tzatziki and taramasalata with warm pita`}],why:`A Greek taverna run by the same family since 1978 in Melbourne's Greek Precinct, famous for gyros carved from the spit until late.`,tip:`Open late on Fridays and Saturdays; bookings only for large groups.`,praise:[`Generous souvlaki and gyros`,`Open late`,`Lively, classic taverna feel`],reservation:`walk-in`,reservationNote:`Walk in for a table any time; only large groups need to book`},{id:`young-and-jackson`,name:`Young & Jackson`,area:`Flinders Street (opposite the station)`,lat:-37.8169,lng:144.9668,kind:`bar`,meals:[`lunch`,`dinner`],spend:[25,40],order:[{name:`Chicken parma`,price:30,note:`Crumbed chicken schnitzel topped with tomato sauce and melted cheese`,wiki:`Chicken parmesan`},{name:`Local pint`,price:12,note:`Australian beer from the taps`}],why:`A pub trading on the corner of Flinders and Swanston streets since 1861, home of the famous painting Chloe and a classic chicken parma.`,tip:`The rooftop bar has views over Federation Square; it fills up after work.`,praise:[`Historic pub right opposite Flinders Street Station`,`Rooftop views over the city`,`Solid pub classics`],watchOut:`Touristy and busy after work, with prices to match.`,reservation:`walk-in`,reservationNote:`Pub: walk in for a drink or meal; book ahead only for big groups`},{id:`south-melbourne-market`,name:`South Melbourne Market`,area:`South Melbourne`,lat:-37.8321,lng:144.9567,kind:`market`,meals:[`breakfast`,`lunch`],spend:[5,20],order:[{name:`Dim sims from the South Melbourne Market dim sim stall`,price:3,note:`Large pork and cabbage dumplings, steamed or deep-fried`,wiki:`Dim sim`},{name:`Fresh oysters`,price:3,note:`Freshly shucked oysters from the seafood stalls`}],why:`A neighbourhood market since 1867, best known for its giant, steamed or fried dim sims sold from the same stall for decades.`,tip:`Open Wednesday, Friday, Saturday and Sunday only; take tram 12 or 96 from the city.`,praise:[`Famous oversized dim sims`,`Friendly, local market feel`,`Good fresh produce and deli stalls`],reservation:`walk-in`,reservationNote:`Market: order at the stalls, no bookings`},{id:`chin-chin`,name:`Chin Chin`,area:`Flinders Lane`,lat:-37.8157,lng:144.97,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,80],order:[{name:`Kingfish sashimi with lime, chilli and Thai basil`,price:28,note:`Raw kingfish dressed with lime, chilli and Thai basil`},{name:`Jungle curry`,price:36,note:`Fiery Thai curry made without coconut milk`},{name:`"Feed me" set menu`,price:90,note:`Chef-chosen share menu for the table`}],why:`A loud, buzzy Flinders Lane favourite since 2011, serving punchy Southeast Asian share plates and helping define the laneway dining scene.`,tip:`Bookings are limited and walk-in waits are common; wait in the basement bar.`,praise:[`Bold, punchy flavours`,`Buzzy, fun atmosphere`,`The set menu is a good way to try lots`],watchOut:`Very loud inside; not one for a quiet conversation.`,reservation:`recommended`,reservationNote:`Book online for a set time if you can; otherwise walk in and expect a wait`}],dishes:{"Flat white":{price:[4,6],wiki:`Flat white`},"Hot jam doughnuts":{price:[2,8],wiki:`Jelly doughnut`},"Chicken parma":{price:[24,34],wiki:`Chicken parmesan`},Souvlaki:{price:[12,20],wiki:`Souvlaki`},"Dim sims":{price:[2,4],wiki:`Dim sim`},"Laneway brunch":{price:[20,35],wiki:`Brunch`}}}};export{r as a,a as i,l as n,t as o,s as r,d as t};